#!/usr/bin/env bash# Bash completion for: ollama run <model># Provides completions for model names, handling ':' inside model names._ollama_completions() {    # CRITICAL: only handle completions when subcommand is exactly "run"    if [[ "${COMP_WORDS[1]:-}" != "run" ]]; then        return    fi    # Preserve original COMP_WORDBREAKS so we can restore it later    local orig_wordbreaks="$COMP_WORDBREAKS"    # Remove ':' from wordbreaks so model names containing ':' are treated as single words    COMP_WORDBREAKS=${COMP_WORDBREAKS//:/}    # Use bash-completion helper to populate $cur and $prev without splitting on ':'    _get_comp_words_by_ref -n : cur prev    # Restore original COMP_WORDBREAKS immediately after parsing    COMP_WORDBREAKS="$orig_wordbreaks"    # Ensure ollama exists before attempting to call it    if ! command -v ollama &>/dev/null; then        return    fi    # Obtain model list from `ollama list`, skipping the header line and extracting the first column    # Example expected output:    # NAME        TYPE   SIZE    # foo/bar:v1  local  1.2GB    # We want "foo/bar:v1" etc.    local model_list    model_list=$(ollama list 2>/dev/null | awk 'NR > 1 {print $1}')    # If no models found, nothing to complete    if [[ -z "$model_list" ]]; then        return    fi    # Populate COMPREPLY using compgen against the dynamically retrieved model list    COMPREPLY=( $(compgen -W "$model_list" -- "$cur") )    # Trim leading text when ':' is present so completions display sensibly    __ltrim_colon_completions "$cur"}# Register completion function for the 'ollama' commandcomplete -F _ollama_completions ollama